
const WORDS=[{"id": 0, "w": "正经", "p": "zhèngjing", "t": "形容词", "m": "đứng đắn, nghiêm chỉnh, chính đáng", "coll": "正经事、正经工作", "s": "讨论正经事的时候，他总能收起平时爱开玩笑的样子。"}, {"id": 1, "w": "玩意儿", "p": "wányìr", "t": "名词", "m": "đồ chơi, đồ vật", "coll": "小玩意儿、新鲜玩意儿", "s": "爷爷对这些新鲜玩意儿很好奇，常常请孙女教他使用。"}, {"id": 2, "w": "憋", "p": "biē", "t": "动词", "m": "kìm nén, nén", "coll": "憋着不说、憋了一肚子话", "s": "他憋了一肚子话，直到晚饭后才找到机会告诉家人。"}, {"id": 3, "w": "报警", "p": "bàojǐng", "t": "动词", "m": "báo cảnh sát", "coll": "及时报警、拨电话报警", "s": "发现有人撬门，邻居立即报警，并提醒住户注意安全。"}, {"id": 4, "w": "绑架", "p": "bǎngjià", "t": "动词", "m": "bắt cóc", "coll": "绑架案件、遭到绑架", "s": "这部电影围绕一起绑架案件展开，情节紧张，但最终真相大白。"}, {"id": 5, "w": "受罪", "p": "shòuzuì", "t": "动词", "m": "bị giày vò, gặp chuyện phiền muộn", "coll": "让人受罪、白白受罪", "s": "鞋子不合脚，走起路来实在受罪，他只好提前回家。"}, {"id": 6, "w": "吼", "p": "hǒu", "t": "动词", "m": "gào to, thét lên", "coll": "大声吼、吼了一声", "s": "他朝着远处大声吼了一声，提醒伙伴停下脚步。"}, {"id": 7, "w": "智能", "p": "zhìnéng", "t": "名词／形容词", "m": "thông minh", "coll": "智能设备、人工智能", "s": "这些智能设备给生活带来了方便，但也需要合理使用。"}, {"id": 8, "w": "奴隶", "p": "núlì", "t": "名词", "m": "nô lệ", "coll": "成为奴隶、奴隶制度", "s": "我们应该学会管理时间，不要成为手机的奴隶。"}, {"id": 9, "w": "麻木", "p": "mámù", "t": "形容词", "m": "tê/lãnh đạm, thờ ơ", "coll": "表情麻木、变得麻木", "s": "长期忽视身边的人，可能让我们对他人的感受逐渐变得麻木。"}, {"id": 10, "w": "狼吞虎咽", "p": "lángtūn hǔyàn", "t": "成语", "m": "ăn ngấu nghiến, nuốt lấy nuốt để", "coll": "狼吞虎咽地吃、吃得狼吞虎咽", "s": "忙了一整天，他回到家后狼吞虎咽地吃完了一碗饭。"}, {"id": 11, "w": "伺候", "p": "cìhou", "t": "动词", "m": "phục dịch, hầu hạ", "coll": "伺候病人、伺候花草", "s": "老人每天花些时间伺候院子里的花草，日子过得十分充实。"}, {"id": 12, "w": "眨", "p": "zhǎ", "t": "动词", "m": "nháy, chớp", "coll": "眨眼睛、眨了眨眼", "s": "小女孩眨了眨眼，好奇地问这台机器为什么会说话。"}, {"id": 13, "w": "索性", "p": "suǒxìng", "t": "副词", "m": "dứt khoát", "coll": "索性关机、索性留下", "s": "既然网络一直不稳定，他索性关掉手机，专心读起书来。"}, {"id": 14, "w": "作息", "p": "zuòxī", "t": "名词／动词", "m": "làm việc và nghỉ ngơi", "coll": "调整作息、作息规律", "s": "假期结束前，她开始调整作息，准备迎接新学期。"}, {"id": 15, "w": "着手", "p": "zhuóshǒu", "t": "动词", "m": "bắt tay vào làm, bắt đầu làm", "coll": "着手准备、着手解决", "s": "明确问题以后，我们就应该着手寻找解决办法。"}, {"id": 16, "w": "安置", "p": "ānzhì", "t": "动词", "m": "thu xếp, bố trí", "coll": "妥善安置、安置行李", "s": "工作人员先安置好远道而来的客人，再安排参观活动。"}, {"id": 17, "w": "防止", "p": "fángzhǐ", "t": "动词", "m": "đề phòng, ngăn ngừa", "coll": "防止意外、防止分心", "s": "上课时把手机调成静音，可以防止提示音打断讨论。"}, {"id": 18, "w": "薄弱", "p": "bóruò", "t": "形容词", "m": "yếu kém, yếu đuối, nhu nhược", "coll": "基础薄弱、薄弱环节", "s": "发现自己的基础薄弱，她决定先把基本知识补扎实。"}, {"id": 19, "w": "精致", "p": "jīngzhì", "t": "形容词", "m": "tinh xảo, tuyệt đẹp", "coll": "精致的礼物、做工精致", "s": "这个小盒子做工精致，上面还刻着细小的花纹。"}, {"id": 20, "w": "庄重", "p": "zhuāngzhòng", "t": "形容词", "m": "trang trọng, long trọng", "coll": "神情庄重、庄重的场合", "s": "在这个庄重的场合，每个人都认真倾听，没有随意交谈。"}, {"id": 21, "w": "分散", "p": "fēnsàn", "t": "动词", "m": "phân tán", "coll": "分散注意力、分散人群", "s": "不断弹出的消息容易分散注意力，让人难以完成手头的任务。"}, {"id": 22, "w": "僵硬", "p": "jiāngyìng", "t": "形容词", "m": "cứng đờ", "coll": "动作僵硬、表情僵硬", "s": "第一次登台时，他的动作有些僵硬，练习几次后才逐渐自然起来。"}, {"id": 23, "w": "四肢", "p": "sìzhī", "t": "名词", "m": "tứ chi, tay chân", "coll": "活动四肢、四肢无力", "s": "坐了很久以后，他站起来活动了一下四肢，又继续整理资料。"}, {"id": 24, "w": "特长", "p": "tècháng", "t": "名词", "m": "sở trường, năng khiếu", "coll": "发挥特长、个人特长", "s": "老师鼓励学生在活动中发挥各自的特长。"}, {"id": 25, "w": "兴高采烈", "p": "xìnggāo cǎiliè", "t": "成语", "m": "phấn khởi, hớn hở", "coll": "兴高采烈地讨论、兴高采烈地出发", "s": "听说明天可以去郊游，孩子们兴高采烈地讨论起要带什么。"}, {"id": 26, "w": "摇滚", "p": "yáogǔn", "t": "名词", "m": "nhạc rốc en rôn", "coll": "摇滚乐、摇滚乐队", "s": "这支摇滚乐队在校园里演出，吸引了不少喜欢音乐的学生。"}, {"id": 27, "w": "一举两得", "p": "yījǔ liǎngdé", "t": "成语", "m": "một công đôi việc", "coll": "一举两得、真是一举两得", "s": "步行去图书馆既能锻炼身体，又能节省车费，真是一举两得。"}, {"id": 28, "w": "冷落", "p": "lěngluò", "t": "动词", "m": "đối xử lạnh nhạt/thờ ơ", "coll": "冷落家人、受到冷落", "s": "聚会时如果只顾着看手机，就容易冷落身边的朋友。"}, {"id": 29, "w": "踏实", "p": "tāshi", "t": "形容词", "m": "yên tâm", "coll": "心里踏实、睡得踏实", "s": "把该完成的工作认真做好以后，他心里才觉得踏实。"}, {"id": 30, "w": "空虚", "p": "kōngxū", "t": "形容词", "m": "trống rỗng", "coll": "感到空虚、内心空虚", "s": "整天无目的地刷手机，并没有让他快乐，反而使他感到空虚。"}, {"id": 31, "w": "要命", "p": "yàomìng", "t": "动词", "m": "chết người, cực kỳ, vô cùng", "coll": "累得要命、急得要命", "s": "找不到重要的文件，他急得要命，最后才发现文件就在桌边。"}, {"id": 32, "w": "粥", "p": "zhōu", "t": "名词", "m": "cháo", "coll": "一碗粥、煮粥", "s": "清晨，厨房里飘来一阵刚煮好的粥的香味。"}, {"id": 33, "w": "消耗", "p": "xiāohào", "t": "动词", "m": "tiêu hao, tiêu xài", "coll": "消耗精力、消耗电量", "s": "长时间使用手机不仅消耗电量，也可能占用本来用于休息的时间。"}, {"id": 34, "w": "弥补", "p": "míbǔ", "t": "动词", "m": "bù đắp", "coll": "弥补不足、弥补遗憾", "s": "认识到自己的不足后，她通过持续练习努力弥补。"}, {"id": 35, "w": "沸腾", "p": "fèiténg", "t": "动词", "m": "sôi sùng sục", "coll": "水沸腾了、人群沸腾", "s": "比赛结果公布时，整个会场顿时沸腾起来。"}, {"id": 36, "w": "弥漫", "p": "mímàn", "t": "动词", "m": "bao phủ, lan khắp, tỏa khắp", "coll": "香气弥漫、弥漫着雾气", "s": "雨后的清晨，山谷里弥漫着一层淡淡的雾气。"}, {"id": 37, "w": "往常", "p": "wǎngcháng", "t": "名词", "m": "thường ngày, mọi ngày", "coll": "像往常一样、与往常不同", "s": "这天早上，他像往常一样走进教室，却发现大家都在等他。"}, {"id": 38, "w": "侦探", "p": "zhēntàn", "t": "名词", "m": "trinh thám, thám tử", "coll": "侦探小说、一位侦探", "s": "她很喜欢读侦探小说，常常尝试根据线索猜测故事的结局。"}, {"id": 39, "w": "案件", "p": "ànjiàn", "t": "名词", "m": "vụ án", "coll": "调查案件、案件真相", "s": "警方正在调查这起案件，希望尽快查明事情的真相。"}, {"id": 40, "w": "突破", "p": "tūpò", "t": "动词", "m": "đột phá", "coll": "取得突破、突破限制", "s": "经过多次尝试，团队终于在关键问题上取得了突破。"}, {"id": 41, "w": "震惊", "p": "zhènjīng", "t": "动词", "m": "làm kinh ngạc, làm ngạc nhiên", "coll": "令人震惊、感到震惊", "s": "听到老朋友突然离开的消息，他感到十分震惊，久久说不出话来。"}, {"id": 42, "w": "彩票", "p": "cǎipiào", "t": "名词", "m": "vé số", "coll": "购买彩票、彩票号码", "s": "他把那张旧彩票夹在书里，早已忘记了购买的日期。"}, {"id": 43, "w": "恐怖", "p": "kǒngbù", "t": "形容词", "m": "khủng khiếp, gây kinh hoàng", "coll": "恐怖电影、恐怖的气氛", "s": "这部恐怖电影通过音乐和光线营造了紧张的气氛。"}, {"id": 44, "w": "袭击", "p": "xíjī", "t": "动词", "m": "tập kích, đột kích", "coll": "遭到袭击、突然袭击", "s": "新闻报道说，那艘船在航行途中遭到了袭击。"}, {"id": 45, "w": "干扰", "p": "gānrǎo", "t": "动词", "m": "quấy nhiễu, làm phiền", "coll": "受到干扰、干扰学习", "s": "为了不受消息干扰，她把手机放在一边，专心完成阅读任务。"}, {"id": 46, "w": "安宁", "p": "ānníng", "t": "形容词／名词", "m": "yên tĩnh, thanh bình", "coll": "生活安宁、片刻安宁", "s": "离开喧闹的街道，他在小院里享受了片刻安宁。"}];
